// Original SVG illustrations for the practices listed in BFP's supplied PDF.
const face = (x, y, color = '#ffd43b', r = 38) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/><path d="M${x-20} ${y-5}q6 9 12 0m16 0q6 9 12 0m-33 23q13 11 26 0" stroke="#262820" stroke-width="4" stroke-linecap="round"/>`;
const heart = (x=180,y=170,color='#f5aad0',scale=1) => `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M0 65C-125-5-68-95 0-45C68-95 125-5 0 65Z" fill="${color}"/></g>`;
const person = (x=180,y=165,color='#1359df') => `<g transform="translate(${x} ${y})"><circle cy="-67" r="29" fill="#ffd43b"/><path d="M-40 5a40 40 0 0 1 80 0v54h-80V5Z" fill="${color}"/><path d="M-21 61v56m42-56v56" stroke="#262820" stroke-width="12" stroke-linecap="round"/></g>`;
const chair = '<path d="M115 185h135v36H115z" fill="#f68a36"/><path d="M130 221v68m105-68v68M112 185v-65" stroke="#a95c28" stroke-width="11" stroke-linecap="round"/>';
const sun = (step) => `<g class="scene-sun" transform="translate(0 ${step===1?35:step===2?14:0})">${face(180,145,'#ffd43b',57)}</g><path d="M65 242q115-85 230 0v57H65v-57Z" fill="#f5aad0"/><path d="M50 270q130-65 260 0" stroke="#f68a36" stroke-width="18" stroke-linecap="round"/>`;
const flower = `<path d="M160 38C214 2 258 50 251 98C310 107 320 167 278 202C298 262 239 296 198 276C165 329 104 304 93 264C33 278 2 221 36 179C-2 133 32 78 80 83C87 29 131 17 160 38Z" fill="#1359df"/><circle cx="157" cy="162" r="79" fill="#f5aad0"/><path d="M120 148q13 20 26 0m22 0q13 20 26 0m-66 31q30 30 59 0" stroke="#262820" stroke-width="6" stroke-linecap="round"/>`;

export function sceneArt(id, step = 1) {
  let art;
  switch (id) {
    case 'breath': art=`<g transform="translate(27 25) scale(.95)">${flower}</g>`; break;
    case 'breath-478': art=`<circle cx="180" cy="180" r="110" fill="#fffdf8" stroke="#ddd7ed" stroke-width="13"/><path d="M180 70a110 110 0 1 1-1 0" stroke="#1359df" stroke-width="13" stroke-linecap="round"/>${face(180,180,'#f5aad0',65)}<circle class="pattern-marker" cx="180" cy="70" r="13" fill="#f68a36" stroke="#faf7f1" stroke-width="4"/>`; break;
    case 'box': art=`<rect x="75" y="75" width="210" height="210" rx="18" fill="#fffdf8" stroke="#1359df" stroke-width="14"/>${face(180,180,'#ffd43b',58)}<circle class="pattern-marker" cx="75" cy="75" r="14" fill="#f68a36" stroke="#faf7f1" stroke-width="4"/>`; break;
    case 'stretch': art=`${person(180,165)}<g class="stretch-arms"><path d="M143 172 95 ${step===2?'73':'130'}M217 172 265 ${step===2?'73':'130'}" stroke="#1359df" stroke-width="20" stroke-linecap="round"/></g><path d="m76 97-6-20m217 20 6-20" stroke="#f68a36" stroke-width="5" stroke-linecap="round"/>`; break;
    case 'wash-hands': art=`<path d="M95 103h98V81h-54" stroke="#1359df" stroke-width="18" stroke-linecap="round"/><g class="water-stream"><path d="M193 135v55m-15-42v35m30-35v35" stroke="#87bce9" stroke-width="9" stroke-linecap="round"/></g><path d="M84 242c55-38 68-10 109-21 34-11 75-13 88 11-65 54-139 61-197 10Z" fill="#f5aad0"/><path d="M109 264c60-12 82-4 134-23" stroke="#f68a36" stroke-width="15" stroke-linecap="round"/><circle cx="244" cy="181" r="10" fill="#fffdf8"/><circle cx="272" cy="160" r="6" fill="#fffdf8"/>`; break;
    case 'stop': art=`<path d="m142 64 76 0 54 54v76l-54 54h-76l-54-54v-76z" fill="#f68a36"/>${face(180,157,'#ffd43b',51)}<g fill="#1359df"><circle cx="122" cy="292" r="${step===1?11:5}"/><circle cx="180" cy="292" r="${step===2?11:5}"/><circle cx="238" cy="292" r="${step===3?11:5}"/></g>`; break;
    case 'transition': art=`<path d="M120 307c-65-100 126-73 85-157S129 65 226 49" stroke="#ddd6e9" stroke-width="65" stroke-linecap="round"/><g class="scene-footsteps" fill="#1359df"><ellipse cx="148" cy="251" rx="13" ry="25" transform="rotate(-35 148 251)"/><ellipse cx="184" cy="205" rx="13" ry="25" transform="rotate(30 184 205)"/><ellipse cx="186" cy="129" rx="13" ry="25" transform="rotate(-20 186 129)"/></g><path d="m221 68 6-22 20 11" stroke="#f68a36" stroke-width="6" stroke-linecap="round"/>`; break;
    case 'kindness': art=`${heart(180,160,'#f5aad0',.85)}<g class="kindness-rays" stroke="#f68a36" stroke-width="7" stroke-linecap="round"><path d="m76 123-18-10m225 10 18-10M180 65V43M96 237l-16 15m184-15 16 15"/></g>${face(180,169,'#ffd43b',32)}`; break;
    case 'intention': art=`<path d="M80 287h200" stroke="#a9c5a6" stroke-width="12" stroke-linecap="round"/><path d="M180 276V92" stroke="#1359df" stroke-width="13" stroke-linecap="round"/><path d="m144 122 36-43 36 43" stroke="#1359df" stroke-width="13" stroke-linecap="round" stroke-linejoin="round"/>${face(180,207,'#f5aad0',45)}<path d="m261 88 5 14 14 5-14 5-5 14-5-14-14-5 14-5z" fill="#ffd43b"/>`; break;
    case 'compassion': art=`${heart(180,147,'#f5aad0',.85)}<path d="M66 209c25-15 50 29 78 32m150-32c-25-15-50 29-78 32" stroke="#f68a36" stroke-width="27" stroke-linecap="round"/><path d="M142 241q38 24 76 0" stroke="#f68a36" stroke-width="26" stroke-linecap="round"/>${face(180,147,'#ffd43b',35)}`; break;
    case 'hug': art=`<g transform="translate(-30 20)">${person(150,163,'#f5aad0')}</g><g transform="translate(30 20)">${person(210,163,'#f68a36')}</g><path d="M110 175q69 70 140 0" stroke="#1359df" stroke-width="17" stroke-linecap="round"/>${heart(180,89,'#1359df',.3)}`; break;
    case 'eating': art=`<circle cx="180" cy="183" r="112" fill="#fffdf8"/><circle cx="180" cy="183" r="86" stroke="#ddd7ed" stroke-width="4"/><path d="M112 214c0-94 136-94 136 0H112Z" fill="#f68a36"/><path d="M180 128c-1-28 27-44 44-36-3 24-23 36-44 36Z" fill="#5b947b"/><path d="M136 200q44-61 88 0" stroke="#ffd43b" stroke-width="10" stroke-linecap="round"/><g class="food-specks" fill="#fffdf8"><circle cx="164" cy="172" r="4"/><circle cx="184" cy="185" r="4"/><circle cx="202" cy="165" r="4"/></g>`; break;
    case 'morning': art=sun(step); break;
    case 'stool': art=`${chair}<circle cx="180" cy="102" r="30" fill="#ffd43b"/><path d="M143 173v-26a37 37 0 0 1 74 0v26" fill="#f5aad0"/><path d="M143 172h74" stroke="#1359df" stroke-width="15" stroke-linecap="round"/><path d="M159 201v-23m42 23v-23" stroke="#262820" stroke-width="12" stroke-linecap="round"/>`; break;
    case 'door': art=`<path d="M90 304V70h180v234" fill="#f5aad0"/><path d="M110 304V90h140v214" fill="#fffdf8"/><path d="m110 90 92 35v179h-92V90Z" fill="#1359df"/><circle cx="185" cy="208" r="6" fill="#ffd43b"/><path d="m235 198 22 16-22 16" stroke="#f68a36" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>`; break;
    case 'body': art=`${person(180,170,'#a9c5a6')}<circle class="body-focus" cx="180" cy="${step===1?103:step===2?170:262}" r="${step===2?60:44}" fill="#f5aad0" fill-opacity=".45" stroke="#1359df" stroke-width="4"/><path d="M160 101q6 8 12 0m16 0q6 8 12 0" stroke="#262820" stroke-width="3" stroke-linecap="round"/>`; break;
    case 'clouds': art=`<circle cx="250" cy="115" r="38" fill="#ffd43b"/><g class="cloud-drift"><path d="M85 177c-21-46 47-84 74-43 18-52 84-29 76 13 48-10 62 60 17 65H102c-41 0-53-33-17-35Z" fill="#fffdf8"/><path d="M133 168q8 11 16 0m23 0q8 11 16 0" stroke="#262820" stroke-width="4" stroke-linecap="round"/></g><path d="M90 275q90-42 180 0" stroke="#a9c5a6" stroke-width="15" stroke-linecap="round"/>`; break;
    case 'listening': art=`<path d="M136 145V96l104-25v133" stroke="#1359df" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="114" cy="151" rx="28" ry="21" fill="#1359df"/><ellipse cx="218" cy="209" rx="28" ry="21" fill="#1359df"/><g class="sound-lines" stroke="#f68a36" stroke-width="9" stroke-linecap="round"><path d="M85 253v27m28-42v57m28-45v33m28-58v80m28-55v33m28-45v57m28-42v27"/></g>`; break;
    case 'gratitude': art=`${face(180,176,'#ffd43b',83)}<g class="kindness-rays" fill="#f5aad0"><path d="m80 92 6 18 18 6-18 6-6 18-6-18-18-6 18-6zM278 224l5 15 15 5-15 5-5 15-5-15-15-5 15-5z"/></g><path d="M117 286q63 20 126 0" stroke="#f68a36" stroke-width="12" stroke-linecap="round"/>`; break;
    case 'focus': art=`<g class="focus-surroundings" opacity="${step===2?'.15':'.5'}"><rect x="63" y="70" width="54" height="54" rx="13" fill="#f5aad0"/><path d="m264 84 29 51h-58z" fill="#a9c5a6"/><circle cx="278" cy="271" r="25" fill="#ffd43b"/><path d="m72 251 20 35-40 0z" fill="#f68a36"/></g><circle cx="180" cy="180" r="76" fill="#1359df"/><circle cx="180" cy="180" r="${step===2?88:98}" stroke="#1359df" stroke-opacity=".3" stroke-width="3"/>${face(180,180,'#f68a36',43)}`; break;
    default: throw new Error(`Missing illustration: ${id}`);
  }
  return art;
}

export function sceneMarkup(id, step = 1, paused = false) {
  const art = sceneArt(id, step);
  const background = ['body','stretch','stool','stop'].includes(id)?'#e8eee4':['kindness','compassion','hug','gratitude'].includes(id)?'#f7e5ec':'#edebf6';
  return `<div class="observation-scene experience-scene experience-${id} scene-step-${step} ${paused?'is-paused':''}" aria-hidden="true"><svg viewBox="0 0 360 360" fill="none"><circle cx="180" cy="180" r="170" fill="${background}"/>${art}</svg></div>`;
}
